export type ParsedWrapAssetInstruction<
  TProgram extends string = typeof ENVELOPE_VAULT_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>
  accounts: {
    user: TAccountMetas[0]
    assetVault: TAccountMetas[1]
    vaultAuthority: TAccountMetas[2]
    /** Pins which asset this is; `asset_vault`'s seeds tie the two together. */
    underlyingMint: TAccountMetas[3]
    userUnderlying: TAccountMetas[4]
    vaultTokenAccount: TAccountMetas[5]
    confidentialMint: TAccountMetas[6]
    userConfidential: TAccountMetas[7]
    tokenProgram: TAccountMetas[8]
    token2022Program: TAccountMetas[9]
  }
  data: WrapAssetInstructionData
}

export function parseWrapAssetInstruction<TProgram extends string, TAccountMetas extends readonly AccountMeta[]>(
  instruction: Instruction<TProgram> & InstructionWithAccounts<TAccountMetas> & InstructionWithData<ReadonlyUint8Array>,
): ParsedWrapAssetInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 10) {
    throw new SolanaError(SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS, {
      actualAccountMetas: instruction.accounts.length,
      expectedAccountMetas: 10,
    })
  }
  let accountIndex = 0
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!
    accountIndex += 1
    return accountMeta
  }
  return {
    programAddress: instruction.programAddress,
    accounts: {
      user: getNextAccount(),
      assetVault: getNextAccount(),
      vaultAuthority: getNextAccount(),
      underlyingMint: getNextAccount(),
      userUnderlying: getNextAccount(),
      vaultTokenAccount: getNextAccount(),
      confidentialMint: getNextAccount(),
      userConfidential: getNextAccount(),
      tokenProgram: getNextAccount(),
      token2022Program: getNextAccount(),
    },
    data: getWrapAssetInstructionDataDecoder().decode(instruction.data),
  }
}
